INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-04' FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Post-issuance electronic transmission via the Ministry of Finance''s E-Invoice Platform -- eGUI mandatory for all business-tax-registered entities since 1 January 2021', 'This deep-dive page reflects publicly available Ministry of Finance guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current requirements directly on the Ministry of Finance''s E-Invoice Platform or with a Taiwan tax adviser before relying on this page for compliance decisions.', 'Taiwan''s eGUI (electronic Government Uniform Invoice) system built up in stages rather than arriving all at once. Cross-border VAT registration and eGUI obligations for foreign digital service providers began 1 May 2017. The universal mandate followed on 1 January 2021, requiring every business-tax-registered entity -- domestic and foreign, B2B and B2C -- to issue eGUIs in structured format. An amendment to the Value-Added and Non-Value-Added Business Tax Act, published 3 September 2024, then formalized transmission deadlines (7 days for B2B, 2 days for B2C) and strengthened penalties. Most recently, the Message Implementation Guideline (MIG) 4.0 XML format, introduced 1 January 2024, became the sole valid eGUI format once the legacy MIG 3.1/3.2 transition period closed on 31 December 2025.', 'A compliant eGUI must be issued in the current Message Implementation Guideline (MIG) 4.0 XML format -- the older MIG 3.1/3.2 formats were retired on 31 December 2025 and are no longer accepted. Invoices are transmitted to the Ministry of Finance''s E-Invoice Platform, operated together with the Fiscal Information Agency (FIA).', 'The mandate covers every business-tax-registered entity in Taiwan -- domestic and foreign, B2B and B2C -- since 1 January 2021. Foreign digital service providers selling into Taiwan have been separately in scope for cross-border VAT registration and eGUI issuance since 1 May 2017, once they cross a registration threshold. A September 2025 Peppol Authority adoption adds a voluntary cross-border exchange option on top of the existing domestic mandate; it does not change who is required to issue eGUIs.', 'Getting ready means confirming your invoicing or ERP system''s eGUI output already migrated to MIG 4.0 (mandatory since 1 January 2026), building the 7-day B2B / 2-day B2C transmission deadlines into your workflow, and -- for foreign digital service providers -- confirming your cross-border VAT registration status.', 'Taiwan backs its e-invoicing rules with fines under the amended Business Tax Act: TWD 1,500-15,000 for late or missing transmission, with escalating penalties for repeat violations, and separate exposure for inaccurate transmitted invoice data.', 'Taiwan''s Ministry of Finance operates eGUI (electronic Government Uniform Invoice) as a post-issuance transmission model: an invoice is valid once it reaches the buyer, with transmission to the MOF''s E-Invoice Platform a separate, timed obligation rather than a precondition for validity. The mandate became universal on 1 January 2021, covering every business-tax-registered entity for both B2B and B2C transactions. An amendment to the Business Tax Act (published 3 September 2024) set transmission deadlines of 7 days for B2B invoices and 2 days for B2C invoices, backed by fines of TWD 1,500-15,000. Since 1 January 2026, the MIG 4.0 XML format is the only valid eGUI format -- the legacy MIG 3.1/3.2 formats no longer qualify. In September 2025, Taiwan additionally became a Peppol Authority, a voluntary initiative to standardize cross-border invoicing with network members including Australia, Japan, Malaysia, New Zealand, Singapore, and the UK.', '🇹🇼' FROM countries WHERE name_en = 'Taiwan';
