INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Format", "Message Implementation Guideline (MIG) 4.0 XML -- the sole valid eGUI format since 1 January 2026"], ["Legacy format", "MIG 3.1/3.2, permitted during a transition period through 31 December 2025, now retired"], ["Reporting platform", "Ministry of Finance''s E-Invoice Platform, operated with the Fiscal Information Agency (FIA)"], ["Legal basis", "Value-Added and Non-Value-Added Business Tax Act (BTA), amended 7 August 2024 / published 3 September 2024"]]', 'Confirm your invoicing or ERP system''s eGUI output has completed the MIG 4.0 migration -- MIG 3.1/3.2 submissions have been rejected outright since 1 January 2026.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Business registration", "Taiwan Uniform Business Number, registered for business tax"], ["Registration route", "Ministry of Finance''s E-Invoice Platform, or a certified invoicing/software partner"], ["Foreign digital providers", "Register under the cross-border electronic-services VAT regime once above the registration threshold"], ["Governing bodies", "Ministry of Finance (MOF) and Fiscal Information Agency (FIA)"]]', 'Foreign businesses without a Taiwan presence should confirm their local agent or certified invoicing partner is registered and filing on their behalf.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Structured format required", "MIG 4.0 XML -- PDFs and other unstructured formats do not qualify as valid eGUIs"], ["Core fields", "Issuer/buyer identifiers, invoice track-and-number sequence, itemized sales detail, VAT amount"], ["Timing", "Must be transmitted within 7 days (B2B) or 2 days (B2C) of issuance"], ["Retention", "Standard Taiwan bookkeeping retention rules apply -- confirm the current period with a tax adviser"]]', 'The transmission-timing requirement sits on top of the format requirement -- a correctly formatted eGUI transmitted late is still a compliance failure.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The issue-then-transmit flow', 'A Taiwan eGUI moves through this sequence -- note this is post-issuance reporting, not real-time clearance:', 'The invoice is already legally valid once it reaches the buyer -- the MOF is not asked to approve it first, unlike the clearance-model mandates covered elsewhere in this tracker (Colombia, Argentina, Jordan).');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'eGUI issued to buyer in MIG 4.0 structured format');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Legally valid immediately -- no MOF pre-approval needed');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Transmitted to the MOF E-Invoice Platform within 7 days (B2B) or 2 days (B2C)');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'MOF cross-checks transmitted invoices against filed VAT returns');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s in scope, and since when', '[["Domestic business-tax-registered entities", "Covered since 1 January 2021, B2B and B2C"], ["Foreign digital service providers (above threshold)", "Covered for cross-border VAT/eGUI since 1 May 2017"], ["Cross-border sellers via Peppol", "Voluntary since 22 September 2025 -- not a mandatory requirement"]]', 'The 2025 Peppol Authority adoption is explicitly voluntary -- it adds an international exchange option alongside the domestic mandate rather than replacing or expanding who must comply.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Cross-border context: Peppol adoption', '[["Authority", "Digital Industry Agency (under the Ministry of Digital Affairs)"], ["Adopted", "22 September 2025"], ["Status", "Voluntary -- localized Peppol specifications still under development"], ["Named network members", "Australia, Japan, Malaysia, New Zealand, Singapore, United Kingdom"]]', 'All six named Peppol network members are separately tracked jurisdictions in this compliance corner -- worth checking if you already trade e-invoices with any of them.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💰 TWD 1,500-15,000 for late or inaccurate transmission', NULL, NULL, 'The Business Tax Act amendment published 3 September 2024 set fines of TWD 1,500-15,000 for missing the 7-day (B2B) or 2-day (B2C) transmission deadline, or for transmitting inaccurate invoice data. Penalties escalate for repeated violations.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📅 A mandate built up in stages', NULL, NULL, 'Taiwan''s eGUI history moved in four distinct steps: cross-border VAT/eGUI obligations for foreign digital providers from 2017, the universal domestic mandate from 2021, transmission deadlines and stronger penalties from the 2024 BTA amendment, and MIG 4.0 becoming the sole valid format from 2026. Each step changed a different part of the obligation -- who''s covered, then how fast, then what format -- rather than one single mandate date.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌐 Cross-border: Peppol is additive, not a new mandate', NULL, NULL, 'Taiwan''s September 2025 Peppol Authority adoption is a voluntary cross-border initiative overseen by the Digital Industry Agency -- it does not change domestic eGUI obligations or introduce a new compliance deadline. Treat it as an emerging option for trade with other Peppol network members (Australia, Japan, Malaysia, New Zealand, Singapore, the UK), not as a requirement.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Late or missing transmission of a B2B eGUI (beyond 7 days)', 'TWD 1,500-15,000', 'Escalates for repeat violations');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Late or missing transmission of a B2C eGUI (beyond 2 days)', 'TWD 1,500-15,000', 'Escalates for repeat violations');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Inaccurate or erroneous transmitted invoice data', 'TWD 1,500-15,000', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm you''re covered -- virtually every business-tax-registered entity is', 'Domestic B2B and B2C entities have been covered since 1 January 2021; there is no small-business carve-out the way some other mandates have.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your eGUI output has migrated to MIG 4.0', 'MIG 3.1/3.2 submissions have been rejected outright since 1 January 2026 -- if your invoicing or ERP system hasn''t upgraded, transmissions will fail.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build the 7-day / 2-day transmission clock into your workflow', 'B2B eGUIs must reach the MOF platform within 7 days of issuance, B2C within 2 days -- treat these as hard deadlines with fines attached, not soft targets.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Foreign digital service providers: confirm your cross-border VAT registration', 'If you sell digital services into Taiwan above the registration threshold, confirm your VAT registration and eGUI issuance obligations are current -- this track has applied since 2017, separate from the 2021 domestic mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Taiwan';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch Peppol developments if you trade with other network members', 'Taiwan''s September 2025 Peppol Authority adoption is voluntary today, but worth tracking if you already exchange e-invoices with Australia, Japan, Malaysia, New Zealand, Singapore, or the UK.');
